import{_ as o,a0 as s,w as r,s as p,ao as l,I as a,x as n,a1 as i,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"解決Ubuntu 14.04 Unity桌面環境登錄後凍結問題 | LCTT x X-CMD","titleTemplate":false,"description":"解決Ubuntu 14.04 Unity桌面環境登錄後凍結問題 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"解決Ubuntu 14.04 Unity桌面環境登錄後凍結問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"解決Ubuntu 14.04 Unity桌面環境登錄後凍結問題 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Fix Unity Freezes After Login In Ubuntu 14.04 [Quick Tip]","title":"解決Ubuntu 14.04 Unity桌面環境登錄後凍結問題","tag":"201405","desc":""},"relativePath":"201405/Fix Unity Freezes After Login In Ubuntu 14.04 [Quick Tip].md","filePath":"[post].md"}'),d={name:"201405/Fix Unity Freezes After Login In Ubuntu 14.04 [Quick Tip].md"};function g(U,t,f,y,b,m){const e=s("Link");return r(),p("div",null,[t[11]||(t[11]=l(`<h1 id="解決ubuntu-14-04-unity桌面環境登錄後凍結問題" tabindex="-1">解決Ubuntu 14.04 Unity桌面環境登錄後凍結問題 <a class="header-anchor" href="#解決ubuntu-14-04-unity桌面環境登錄後凍結問題" aria-label="Permalink to “解決Ubuntu 14.04 Unity桌面環境登錄後凍結問題”">​</a></h1><p>如果你把Ubuntu從13.10更新到14.04，你也許會遇到<strong>用Unity桌面環境登錄時凍結的現象</strong>。引導進入Ubuntu14.04，輸入驗證信息，系統會掛起，凍結在那裏。如果你稍微幸運些，你還能看到鼠標光標、桌面背景，僅此而已。<strong>沒有Unity觸發器，也沒有頂部面板</strong>等等。你的ubuntu基本上不可用了。</p><p>缺少Unity觸發器和麪板以及系統凍結的問題，可以通過重新安裝Unity來解決。讓我們看看怎麼做：</p><h3 id="重新安裝14-04的unity-以解決系統凍結的問題" tabindex="-1">重新安裝14.04的Unity 以解決系統凍結的問題### <a class="header-anchor" href="#重新安裝14-04的unity-以解決系統凍結的問題" aria-label="Permalink to “重新安裝14.04的Unity 以解決系統凍結的問題###”">​</a></h3><p>好吧，如果你正被困在一個凍結的系統上，按下<strong>Ctrl+Alt+F2</strong>。這會讓你進入一個命令列界面而不是默認的用户桌面界面。切換到命令列界面後，輸入用户名和密碼登錄之後，使用下面的命令重裝Unity桌面環境：</p><pre><code>sudo apt-get update
sudo apt-get install –reinstall ubuntu-desktop
sudo apt-get install unity
sudo shutdown -r now
</code></pre><p>最後一個命令是重啓系統，重啓之後，你的Unity應該就變好了。</p><h3 id="解決nvidia顯卡的unity凍結問題" tabindex="-1">解決Nvidia顯卡的Unity凍結問題### <a class="header-anchor" href="#解決nvidia顯卡的unity凍結問題" aria-label="Permalink to “解決Nvidia顯卡的Unity凍結問題###”">​</a></h3><p>我沒有使用過Nvidia的顯卡，但是我找到了別人解決這個問題的方法。儘管上面的技巧對我來説有效，但是我沒有過驗證下面的命令。使用Nvidia的用户，請告訴我下面的步驟是否工作：</p><p>和上面一樣使用<strong>Ctrl+Alt+F2</strong>登錄到命令列界面，輸入下面的命令：</p><pre><code>sudo apt-get update
sudo apt-get install –reinstall ubuntu-desktop
sudo apt-get install unity
sudo apt-get remove –purge nvidia*
sudo shutdown -r now
</code></pre><p>如果重啓之後Unity恢復了，記得重新安裝你的Nvidia顯卡的驅動，因為你已經卸載了它。</p><p>我希望這些技巧能夠幫助你從凍結的unbuntu 14.04中恢復。最後，任何的問題和建議都歡迎來提。</p><hr>`,14)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),i(e,{href:"http://itsfoss.com/fix-unity-freezes-after-login-ubuntu-14-04/"},{default:u(()=>[...t[0]||(t[0]=[n("http://itsfoss.com/fix-unity-freezes-after-login-ubuntu-14-04/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=n("譯者：",-1)),i(e,{href:"https://github.com/ggaaooppeenngg"},{default:u(()=>[...t[2]||(t[2]=[n("ggaaooppeenngg",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:u(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const _=o(d,[["render",g]]);export{C as __pageData,_ as default};
